  "warehouse_id": "a832b544eb7dc3fe",
  "wait_timeout": "50s",
  "statement": "CREATE TABLE IF NOT EXISTS workspace.mlpab679845.incrementalf3c1bf (row_id STRING NOT NULL, account_id STRING, event_time BIGINT NOT NULL, amount DOUBLE, category STRING, CONSTRAINT incrementalf3c1bf_pk PRIMARY KEY (row_id, event_time TIMESERIES)) TBLPROPERTIES (delta.enableChangeDataFeed = true)"
