databricks api post /api/2.0/sql/statements --json '{
  "warehouse_id": "a832b544eb7dc3fe",
  "wait_timeout": "50s",
  "statement": "MERGE INTO workspace.mlpab679845.incrementalf3c1bf t USING (SELECT row_id, account_id, CAST(event_time AS BIGINT) AS event_time, CAST(amount AS DOUBLE) AS amount, category FROM read_files(\"/Volumes/workspace/mlpab679845/raw_increments/*.csv\", format => \"csv\", header => true)) s ON t.row_id = s.row_id AND t.event_time = s.event_time WHEN NOT MATCHED THEN INSERT *"
